 '2018年',
 '科塔—马洪圭守护像坐于巴查姆 tsesah 面具之上，面具背后是本贝阿伦加社团面具，底座为巴加 d’mba 头饰；以叠合挑战分类、商品化与市场/博物馆的价值体系。',
