 '大平原拉科塔（苏族）皮、颜料、玻璃珠与人发制成的衬衫，克利夫兰艺术博物馆藏（1984.1046）。',
 '约1890年',
 '传统上只有拉科塔首席酋长有权穿彩绘衬衫，是以牺牲与勇敢赢得、失职即失去的荣誉；此件作于保留地时期，已成战争老兵的特权；人发束每束代表一次战功，多半由家人捐出。',
