 '约1900年',
 '平原各族重视华美的刺绣或珠饰摇篮：既赐婴儿以精神福佑，也给家庭与制作者（通常为女性亲属）带来声望；制作摇篮被视同「触敌」之勇；此件为抱在臂中，另有木架可靠放。',
