 '约1900年',
 '兽皮袍常以刺绣或珠饰条装点，后来也缝在替代袍子的毯上；此条的圆中十字象征世界、四方与神圣中心；该馆引用奥格拉拉拉科塔圣者黑麋鹿1932年的话说明圆的世界观。',
