 '约1868—1873年',
 '雪日里卡米耶经过阿让特伊住宅的落地窗外；脸部以寥寥几笔快速涂抹，雪与树以粗放断续的纯白与纯绿笔触定形，技法大胆；该馆记录未署名。',
