 '莫奈布面油画，诺曼底渔村普尔维尔海景，克利夫兰艺术博物馆藏（1947.196）。',
 '1882年',
 '莫奈画过数幅普尔维尔，村里有木栈道、宽阔海滩与壮丽悬崖；据其书信，村子本身平平，但风景打动了他，海浪就拍在屋脚；1882年春他住在类似画中悬崖右下小屋的小旅馆。',
