 '重要',
 '莫里索布面油画，以姐姐埃德玛为模特，克利夫兰艺术博物馆藏（1950.89）。',
 '1873年',
 '女子坐在披肩上、视线落在书页，阳伞与扇子丢在草地；白裙映出户外的光影，花纹呼应草地野花；X光显示莫里索改过眼神，原本直视观者，近似马奈的人物处理；而她的人物多专注于事务或私下沉思。',
 'manet,impressionism',
