 '重要',
 '雷诺阿布面油画，乡下女孩向画家之妻阿琳递苹果，克利夫兰艺术博物馆藏（1958.47）。',
 '约1890年',
 '戴草帽的男孩可能是画家的侄子埃德蒙，戴发带的小女孩身份未明；柔和斑驳的阳光中，流畅笔触把人物连成一体，跃起的小狗添一点幽默与动势；该馆推测应完成于东法的埃索瓦。',
 'degas,impressionism',
