 '新爱尔兰（美拉尼西亚）彩绘木柱，嵌海螺盖，克利夫兰艺术博物馆藏（1971.149）。',
 '1800年代',
 '重要人物去世后，村民筹备盛大的马兰根（malagan）葬礼：集粮办宴，雇艺术家雕刻精美的雕像与面具，并邀邻近群体参加；仪式持续数日，有演说、舞蹈、音乐、宴飨与物品交换，以展示雕刻彩绘作品为高潮；宾客离去后，雕刻品被弃置，有时被收存。',
