 '17世纪',
 '西班牙',
 '油画',
 '重要',
 '委拉斯开兹为西班牙宫廷弄臣所作的全身肖像，克利夫兰艺术博物馆藏（1965.15）。',
 '约1631—32年',
 '该馆说明：卡拉巴萨斯是西班牙国王菲利普四世宫廷中的弄臣，有身体与智力上的残障，画家强调这一状态而不是试图掩盖；西班牙宫廷珍视并宠爱有残障的人，而委拉斯开兹改变了他们在肖像中的描绘方式；这件作品用正式的全身宫廷肖像格式，来呈现在当时通常被视为边缘的一类人，并深刻地赋予他人性。',
 'baroque,velazquez',
