 'art-baroque',
 '17世纪',
 '荷兰',
 '油画',
 '重要',
 '哈尔斯1638年题年的女子肖像，克利夫兰艺术博物馆藏（1948.137）。',
 '1638年',
 '该馆说明：哈尔斯的肖像常有大胆而参差的笔触，这幅显示他试验湿中湿技法，即不待下层干透就接续加上颜料层，发际线处混合的笔触暗示了一根根头发；画中人被暂定为阿尔切·迪尔克斯多赫特·帕特尔（1597—1678），即哈勒姆酿酒商兼市长扬·德·瓦埃尔（1594—1663）的妻子；题款称她画时41岁。',
