 '绘画',
 '重要',
 '在画面内对比明与暗的技法，形体主要由明暗区域的交接而非锐利轮廓线来确定。',
 '历代',
 '明暗对照法以明暗对比塑造形体，形体多由亮部与暗部的交接来确定，而不靠清晰的轮廓线。',
