 '绘画',
 '重要',
 '把颜料以厚而不透明的块面涂上画面，通常用蘸饱颜料的画笔或调色刀。',
 '历代',
 '厚涂指把颜料以厚而不透明的块面涂在画面上，通常用蘸足颜料的画笔或调色刀。',
 'oil-painting,rembrandt',
