 '欧洲',
 '绘画',
 '重要',
 '加在画面上、用以改变色调的一层透明到半透明的薄色膜。',
 '历代',
 '在绘画中，罩染是加在画面上的一层透明至半透明的薄色膜，用来改变色调。',
