 '欧洲',
 '绘画',
 '重要',
 '法语意为“骗过眼睛”，指逼真到足以使观者误以为所画对象是真实的图像。',
 '历代',
 '错视画是逼真到可能使观者误以为所绘物体、场景、质感或视点是真实的图像，通常指西方的二维艺术或浅浮雕。',
