 '欧洲',
 '绘画',
 '重要',
 '由三块相连的板组成或装在三块相连板上的画或雕刻，常为外侧两翼可折向中央的形式。',
 '历代',
 '三联画是由三块相连的板组成、或装在三块相连的板上的画或雕刻，外侧两翼常可折向中央，是祭坛画的常见形式。',
 'altarpiece,gothic',
