 '欧洲',
 '绘画',
 '重要',
 '基督教教堂中带图像的绘制或雕刻物，通常有框，置于祭坛后部或挂在祭坛后的墙上。',
 '历代',
 '祭坛画指基督教教堂里绘制或雕刻的带图像的物件，通常有框，立在祭坛后部或挂在祭坛后的墙上，主题多为宗教人物，常含叙事或教诲场景，也可含教堂的赞助人。',
