 'glossary-tools',
 '历代',
 '欧洲',
 '绘画',
 '重要',
 '在画面中强调阴影、黑暗或夜景效果的技法，阴影常使画中人物变得模糊。',
 '历代',
 '暗调法是在画中强调阴影、黑暗或夜景效果的技法；这样的处理通常会使画中的人物变得模糊不清。',
 'chiaroscuro,caravaggio',
