 '17世纪',
 '英国',
 '音乐体裁',
 '重要',
 '巴洛克中期的英国作曲家与管风琴家，极为多产，作品含一百多首歌曲、悲剧歌剧《狄多与埃涅阿斯》与《仙后》的剧乐。',
 '1659—1695年',
 '亨利·珀塞尔是巴洛克中期的英国作曲家与管风琴家。他极为多产，作品包括一百多首歌曲、悲剧歌剧《狄多与埃涅阿斯》，以及为莎士比亚《仲夏夜之梦》改编版《仙后》所写的剧乐。',
 'baroque-music,opera,byrd',
