def entries():
    out=[]
    for r in ROWS:
        (i,t,k,u,era,region,medium,tier,defn,when,overview,related,sources)=r
        out.append({"id":i,"title":t,"kind":k,"unit":u,"era":era,"region":region,
                    "medium":medium,"tier":tier,"def":defn,"when":when,
                    "overview":overview,"related":[x for x in related.split(",") if x],
                    "sources":[x for x in sources.split(",") if x]})
    return out

if __name__=="__main__":
    es=entries()
    print("units",len(UNITS),"entries",len(es))
